```java
package com.example.orders;

import java.util.Map;
import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.RestController;

@SpringBootApplication
public class OrderApplication {
    public static void main(String[] args) {
        SpringApplication.run(OrderApplication.class, args);
    }
}

@RestController
class StatusController {
    @GetMapping("/status")
    Map<String, String> status() {
        return Map.of("status", "up");
    }
}
```

With `spring-boot-starter-web` in the build, Spring Boot 3.3.1 uses Tomcat by default and listens on port `8080` unless configuration changes it. The application supplies the endpoint; the starter and auto-configuration supply the usual server and Spring MVC setup.

```properties
# application.properties
server.port=8080
server.servlet.context-path=/api
```

```java
package com.example.orders;

import java.util.Map;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

@RestController
@RequestMapping("/orders")
class OrderController {
    @GetMapping("/{id}")
    Map<String, Long> find(@PathVariable("id") long id) {
        return Map.of("id", id);
    }
}
```

`GET http://localhost:8080/api/orders/42` reaches this method. The `/api` prefix comes from server configuration, while `/orders/42` comes from the controller mappings.

```java
package com.example.orders;

import org.springframework.boot.context.event.ApplicationReadyEvent;
import org.springframework.boot.web.servlet.context.ServletWebServerInitializedEvent;
import org.springframework.context.event.EventListener;
import org.springframework.stereotype.Component;

@Component
class StartupEvents {
    @EventListener
    void serverInitialized(ServletWebServerInitializedEvent event) {
        int port = event.getWebServer().getPort();
        System.out.println("HTTP server is listening on " + port);
    }

    @EventListener
    void applicationReady(ApplicationReadyEvent event) {
        System.out.println("Application runners have finished");
    }
}
```

```properties
server.port=0
server.shutdown=graceful
spring.lifecycle.timeout-per-shutdown-phase=20s
```

The first listener reports the port chosen by the operating system. The second represents a later lifecycle point. In production, use structured logging and Actuator availability probes instead of building traffic control around `System.out` messages.
